var d = tree.root.get_node("Main/FormationsDialog")
var ok := false
for c in d.find_children("*", "OptionButton", true, false):
	for i in range(c.item_count):
		if str(c.get_item_metadata(i)) == "U_GREY_HUNTERS_A_SPLIT":
			ok = true
return ok

var d = tree.root.get_node("Main/FormationsDialog")
var seen := 0
for c in d.find_children("*", "OptionButton", true, false):
	if c.item_count == 0 or c.get_item_text(0) != "(Auto-select)":
		continue
	seen += 1
	for i in range(c.item_count):
		if str(c.get_item_metadata(i)) == "U_MURDERFANG_A":
			return false
return seen == 1

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sw11e-s4] debug-log ERROR: ", l)
return n
